<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requirePermission('competitors.edit');$pdo=Database::connection();$error='';$success='';$status=(string)($_GET['status']??'pending');$allowedStatuses=['pending','under_review','more_info','approved','rejected','all'];if(!in_array($status,$allowedStatuses,true))$status='pending';
require __DIR__.'/dance-cup-request-summary.php';
require __DIR__.'/bulk-review-controls.php';
function requestPayload(array $request):array{$decoded=json_decode((string)($request['payload_json']??''),true);return is_array($decoded)?$decoded:[];}function profileRequestDiscipline(array $request):array{$payload=requestPayload($request);$type=in_array(($payload['competition_type']??''),['jack_jill','dance_cup'],true)?$payload['competition_type']:'jack_jill';$dance=in_array(($payload['dance_style']??''),['bachata','salsa'],true)?$payload['dance_style']:'bachata';return ['type'=>$type,'dance'=>$dance];}function requestStatusClass(string $status):string{return match($status){'approved'=>'success','rejected'=>'danger','more_info'=>'warning','under_review'=>'info',default=>'secondary'};}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$error='Invalid security token. Refresh the page and try again.';else{$requestId=(int)($_POST['request_id']??0);$action=(string)($_POST['action']??'');$adminNotes=trim((string)($_POST['admin_notes']??''))?:null;$stmt=$pdo->prepare('SELECT * FROM bdc_profile_requests WHERE id=:id FOR UPDATE');try{$pdo->beginTransaction();$stmt->execute(['id'=>$requestId]);$request=$stmt->fetch();if(!$request)throw new RuntimeException('Profile request not found.');$discipline=profileRequestDiscipline($request);$userId=(int)(Auth::user()['id']??0);if($action==='approve'){if($request['request_type']==='profile_update'){$competitorId=(int)($request['competitor_id']??0);if($competitorId<1)throw new RuntimeException('The request is not linked to a competitor.');$beforeStmt=$pdo->prepare('SELECT * FROM bdc_competitors WHERE id=:id');$beforeStmt->execute(['id'=>$competitorId]);$before=$beforeStmt->fetch();if(!$before)throw new RuntimeException('Linked competitor not found.');$resolvedName=trim((string)$request['full_name'])!==''?(string)$request['full_name']:(string)$before['exact_name'];$normalisedName=mb_strtolower(trim(preg_replace('/[^\pL\pN]+/u',' ',$resolvedName)??$resolvedName));$update=$pdo->prepare("UPDATE bdc_competitors SET exact_name=:name,normalised_name=:normalised,email=COALESCE(NULLIF(:email,''),email),phone=COALESCE(NULLIF(:phone,''),phone),instagram=COALESCE(NULLIF(:instagram,''),instagram),country=COALESCE(NULLIF(:country,''),country),photo_url=COALESCE(NULLIF(:photo,''),photo_url) WHERE id=:id");$update->execute(['name'=>$resolvedName,'normalised'=>$normalisedName,'email'=>(string)$request['email'],'phone'=>(string)$request['phone'],'instagram'=>(string)$request['instagram'],'country'=>(string)$request['country'],'photo'=>$request['photo_url']?:'','id'=>$competitorId]);if($discipline['type']==='jack_jill'){$upsert=$pdo->prepare("INSERT INTO bdc_competitor_discipline_profiles(competitor_id,dance_style,dance_role,current_division) VALUES(:cid,:dance,:role,'novice') ON DUPLICATE KEY UPDATE dance_role=IF(VALUES(dance_role)='unknown',dance_role,VALUES(dance_role))");$upsert->execute(['cid'=>$competitorId,'dance'=>$discipline['dance'],'role'=>$request['dance_role']]);if($discipline['dance']==='bachata'){$pdo->prepare("UPDATE bdc_competitors SET dance_role=IF(:role='unknown',dance_role,:role2) WHERE id=:id")->execute(['role'=>$request['dance_role'],'role2'=>$request['dance_role'],'id'=>$competitorId]);}}Auth::audit($userId,'profile_request_approved',['request_id'=>$requestId,'competition_type'=>$discipline['type'],'dance_style'=>$discipline['dance'],'requested_competition_category'=>$request['current_division'],'permanent_division_changed'=>false,'before'=>$before],'competitor',$competitorId);}else{if(trim((string)$request['full_name'])==='')throw new RuntimeException('A name is required before approving a new competitor. Request more information first.');$normalisedName=mb_strtolower(trim(preg_replace('/[^\pL\pN]+/u',' ',(string)$request['full_name'])??(string)$request['full_name']));$legacyRole=$discipline['type']==='jack_jill'&&$discipline['dance']==='bachata'?$request['dance_role']:'unknown';$legacyDivision=$discipline['type']==='jack_jill'&&$discipline['dance']==='bachata'?'novice':'unknown';$insert=$pdo->prepare("INSERT INTO bdc_competitors(exact_name,normalised_name,email,phone,instagram,country,dance_role,current_division,photo_url,status,show_on_leaderboard) VALUES(:name,:normalised,:email,:phone,:instagram,:country,:role,:division,:photo,'active',1)");$insert->execute(['name'=>$request['full_name'],'normalised'=>$normalisedName,'email'=>$request['email']?:null,'phone'=>$request['phone']?:null,'instagram'=>$request['instagram']?:null,'country'=>$request['country']?:null,'role'=>$legacyRole,'division'=>$legacyDivision,'photo'=>$request['photo_url']?:null]);$competitorId=(int)$pdo->lastInsertId();$bdcId='BDC-'.str_pad((string)$competitorId,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE bdc_competitors SET bdc_id=:bdc WHERE id=:id')->execute(['bdc'=>$bdcId,'id'=>$competitorId]);$pdo->prepare('UPDATE bdc_profile_requests SET competitor_id=:cid WHERE id=:id')->execute(['cid'=>$competitorId,'id'=>$requestId]);if($discipline['type']==='jack_jill'){$pdo->prepare("INSERT INTO bdc_competitor_discipline_profiles(competitor_id,dance_style,dance_role,current_division) VALUES(:cid,:dance,:role,'novice') ON DUPLICATE KEY UPDATE dance_role=VALUES(dance_role)")->execute(['cid'=>$competitorId,'dance'=>$discipline['dance'],'role'=>$request['dance_role']]);}Auth::audit($userId,'new_competitor_request_approved',['request_id'=>$requestId,'competition_type'=>$discipline['type'],'dance_style'=>$discipline['dance'],'requested_competition_category'=>$request['current_division'],'permanent_division_changed'=>false],'competitor',$competitorId);} $newStatus='approved';$success='Profile request approved. The requested competition category was retained as event information; permanent division was not changed.';}elseif($action==='reject'){$newStatus='rejected';$success='Profile request rejected.';}elseif($action==='more_info'){$newStatus='more_info';$success='Request marked as requiring more information.';}elseif($action==='under_review'){$newStatus='under_review';$success='Request marked as under review.';}else throw new RuntimeException('Invalid action.');$pdo->prepare('UPDATE bdc_profile_requests SET status=:status,admin_notes=:notes,reviewed_by=:uid,reviewed_at=NOW() WHERE id=:id')->execute(['status'=>$newStatus,'notes'=>$adminNotes,'uid'=>$userId,'id'=>$requestId]);Auth::audit($userId,'profile_request_status_changed',['request_id'=>$requestId,'status'=>$newStatus],'profile_request',$requestId);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}
$where='';$params=[];if($status!=='all'){$where='WHERE r.status=:status';$params['status']=$status;}$sql="SELECT r.*,c.bdc_id,c.exact_name current_name,c.email current_email,c.phone current_phone,c.instagram current_instagram,c.country current_country,c.dance_role current_role,c.current_division current_division_value,c.photo_url current_photo FROM bdc_profile_requests r LEFT JOIN bdc_competitors c ON c.id=r.competitor_id $where ORDER BY FIELD(r.status,'pending','under_review','more_info','approved','rejected'),r.created_at DESC,r.id DESC";$stmt=$pdo->prepare($sql);$stmt->execute($params);$requests=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile Requests | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.request-photo{width:64px;height:76px;object-fit:cover;border-radius:8px;border:1px solid #dee2e6}.change-old{color:#6c757d}.change-new{font-weight:700}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="<?=e(url('admin/'))?>">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="<?=e(url('admin/competitors/'))?>">Competitors</a></div></nav><main class="container py-4"><div class="mb-4"><h1 class="h3 mb-1">Profile Requests</h1><p class="text-muted mb-0">Review shared identity changes and discipline-specific competition profile requests.</p></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="btn-group flex-wrap mb-4"><?php foreach(['pending'=>'Pending','under_review'=>'Under Review','more_info'=>'More Info','approved'=>'Approved','rejected'=>'Rejected','all'=>'All'] as $value=>$label):?><a class="btn <?=$status===$value?'btn-dark':'btn-outline-dark'?>" href="?status=<?=e($value)?>"><?=e($label)?></a><?php endforeach;?></div><?php foreach($requests as $r):$disc=profileRequestDiscipline($r);?><section class="card border-0 shadow-sm mb-3"><div class="card-header bg-white d-flex flex-wrap justify-content-between gap-2 align-items-center"><div><strong><?=e($r['full_name'])?></strong> <span class="badge text-bg-<?=requestStatusClass($r['status'])?>"><?=e(str_replace('_',' ',$r['status']))?></span> <span class="badge text-bg-dark"><?=$disc['type']==='dance_cup'?'BDC Dance Cup':ucfirst($disc['dance']).' Jack & Jill'?></span><div class="small text-muted"><?=e(ucwords(str_replace('_',' ',$r['request_type'])))?> · Submitted <?=e($r['created_at'])?></div></div><?php if($r['competitor_id']):?><a class="btn btn-sm btn-outline-dark" href="<?=e(url('admin/competitors/edit.php?id='.(int)$r['competitor_id']))?>">Open competitor</a><?php endif;?></div><div class="card-body"><div class="row g-4"><div class="col-md-2 text-center"><img class="request-photo" src="<?=e($r['photo_url']?:$r['current_photo']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></div><div class="col-md-7"><div class="mb-3"><strong>Competition Type:</strong> <?=$disc['type']==='dance_cup'?'BDC Dance Cup':'Jack & Jill'?><?php if($disc['type']==='jack_jill'):?> · <strong>Dance:</strong> <?=e(ucfirst($disc['dance']))?><?php endif;?></div><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Field</th><th>Current</th><th>Requested</th></tr></thead><tbody><?php foreach(['Name'=>[$r['current_name'],$r['full_name']],'Email'=>[$r['current_email'],$r['email']],'Phone'=>[$r['current_phone'],$r['phone']],'Instagram'=>[$r['current_instagram'],$r['instagram']],'Country'=>[$r['current_country'],$r['country']]] as $label=>$values):?><tr><th><?=e($label)?></th><td class="change-old"><?=e((string)($values[0]?:'—'))?></td><td class="change-new"><?=e((string)($values[1]?:'—'))?></td></tr><?php endforeach;?><?php if($disc['type']==='jack_jill'):?><tr><th>Role</th><td class="change-old"><?=$disc['dance']==='bachata'?e((string)($r['current_role']?:'—')):'Discipline profile'?></td><td class="change-new"><?=e((string)$r['dance_role'])?></td></tr><tr><th>Competition category</th><td class="change-old"><?=$disc['dance']==='bachata'?e((string)($r['current_division_value']?:'—')):'Discipline profile'?></td><td class="change-new"><?=e((string)$r['current_division'])?><div class="small text-muted">Informational only. Permanent division changes only after a Super Admin-approved competition result.</div></td></tr><?php endif;?></tbody></table></div><?php if($r['notes']):?><div class="alert alert-light border mb-0"><strong>Competitor note:</strong> <?=nl2br(e($r['notes']))?></div><?php endif;?></div><div class="col-md-3"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><label class="form-label">Admin notes</label><textarea class="form-control mb-3" name="admin_notes" rows="4"><?=e((string)$r['admin_notes'])?></textarea><div class="d-grid gap-2"><?php if(!in_array($r['status'],['approved','rejected'],true)):?><button class="btn btn-success" name="action" value="approve">Approve</button><button class="btn btn-outline-info" name="action" value="under_review">Under Review</button><button class="btn btn-outline-warning" name="action" value="more_info">Request More Info</button><button class="btn btn-outline-danger" name="action" value="reject" onclick="return confirm('Reject this request?')">Reject</button><?php else:?><div class="text-muted small">Reviewed <?=e((string)$r['reviewed_at'])?></div><?php endif;?></div></form></div></div></div></section><?php endforeach;?><?php if(!$requests):?><div class="card border-0 shadow-sm"><div class="card-body text-center text-muted py-5">No profile requests found.</div></div><?php endif;?></main></body></html>
